/**
 * The pilot sample: sixty fixed records, spread across kinds and bases.
 *
 * The first desk session is the owner's, and the published figure must not be
 * flattered by easy cases. Drawing from the risk queue would put every
 * unsubstantiated and inferred record on screen first; drawing at random across
 * the strata makes the session a fair sample of what the desk can verify.
 *
 * Everything here is deterministic. The draw is a hash of the seed and the
 * record's identity, never Math.random and never the clock, so the file in
 * `research/desk/pilot-sample.tsv` can be regenerated byte for byte and the
 * test can prove it.
 *
 *   npx tsx scripts/desk-pilot-sample.ts
 *
 * writes the file. With `--pilot`, scripts/admin.ts reads it back and shows the
 * records in the file's order.
 */
import { createHash } from 'node:crypto';
import { readFileSync, writeFileSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath, pathToFileURL } from 'node:url';
import { REVIEWABLE, type Kind } from './desk.ts';

export const PILOT_SEED = 'pilot-2026-11';
export const PILOT_SIZE = 60;
export const PILOT_FILE = 'research/desk/pilot-sample.tsv';
export const PILOT_HEADER = 'kind\tid\tbasis';
/**
 * The dataset the committed sample was drawn from. The sample is fixed on
 * purpose, so once the data moves (a session records reviews, a sync brings new
 * records) the draw cannot be reproduced from the tree alone. This sidecar says
 * which dataset it belongs to, so the test can tell "the sample was drawn from
 * this tree" from "the sample is a fixed record of an earlier draw".
 */
export const PILOT_META_FILE = 'research/desk/pilot-sample.json';

const HERE = dirname(fileURLToPath(import.meta.url));
const ROOT = join(HERE, '..');

export interface PilotEntry {
	kind: Kind;
	id: string;
	basis: string;
}

export interface StratumAllocation {
	kind: Kind;
	basis: string;
	/** Records in this stratum that could be drawn. */
	eligible: number;
	/** The floor the stratum is guaranteed: 2, or 1 when only one record exists. */
	minimum: number;
	/** Its exact proportional share of the seats left after the floors. */
	quota: number;
	/** What the largest-remainder step gave it. */
	allocated: number;
}

export interface PilotSample {
	entries: PilotEntry[];
	allocation: StratumAllocation[];
}

/** The order of the digest. Same record, same seed, same place, every run. */
export function pilotDigest(seed: string, kind: Kind, id: string): string {
	return createHash('sha256').update(`${seed}:${kind}:${id}`).digest('hex');
}

/**
 * A record the desk can verify: one of its kinds, cited by at least one source,
 * and not yet reviewed. A record with a review would make the session replace
 * that review, which is not what a sample of unverified claims is for.
 */
export function pilotEligible(record: any): boolean {
	return Boolean(record) && Array.isArray(record.sources) && record.sources.length > 0 && !record.review;
}

function eligibleByKind(dataset: any): Map<Kind, any[]> {
	const out = new Map<Kind, any[]>();
	for (const kind of Object.keys(REVIEWABLE) as Kind[]) {
		out.set(kind, ((dataset?.[kind] ?? []) as any[]).filter(pilotEligible));
	}
	return out;
}

/**
 * Proportional allocation by largest remainder, with a floor of two per stratum
 * that has at least two records and one for a stratum that has exactly one.
 *
 * The floors are taken first, and the rest of the seats are shared in proportion
 * to each stratum's size. This is the reading of the job that keeps every
 * stratum visible while making the bigger strata carry the session: a pure
 * largest remainder would hand a single seat to a stratum of one, and a pure
 * floor would ignore the sizes.
 */
export function pilotAllocation(
	strata: { kind: Kind; basis: string; eligible: number }[],
	size: number
): StratumAllocation[] {
	const total = strata.reduce((n, s) => n + s.eligible, 0);
	if (!total) throw new Error('no eligible records: the sample would be empty');
	const minimums = strata.map((s) => (s.eligible >= 2 ? 2 : 1));
	let floors = minimums.reduce((a, b) => a + b, 0);
	if (floors > size) throw new Error(`the floors need ${floors} seats, more than the ${size} asked for`);
	const rest = size - floors;
	const quotas = strata.map((s) => (s.eligible * rest) / total);
	const allocated = strata.map((s, i) => Math.max(minimums[i], Math.min(s.eligible, minimums[i] + Math.floor(quotas[i]))));
	// The clamp to eligible can only bind when a stratum is smaller than its
	// floor, which the floor rule rules out. Keep the total exact regardless.
	let left = size - allocated.reduce((a, b) => a + b, 0);
	const order = strata
		.map((s, i) => ({ i, remainder: quotas[i] - Math.floor(quotas[i]), eligible: s.eligible }))
		.sort((a, b) => b.remainder - a.remainder || b.eligible - a.eligible || a.i - b.i);
	for (const { i } of order) {
		if (left <= 0) break;
		if (allocated[i] >= strata[i].eligible) continue;
		allocated[i]++;
		left--;
	}
	if (left !== 0) throw new Error(`the allocation is ${size - left} seats, not ${size}`);
	return strata.map((s, i) => ({
		kind: s.kind,
		basis: s.basis,
		eligible: s.eligible,
		minimum: minimums[i],
		quota: quotas[i],
		allocated: allocated[i]
	}));
}

export function pilotSample(dataset: any, seed: string = PILOT_SEED, size: number = PILOT_SIZE): PilotSample {
	if (size < 1) throw new Error('the sample size must be positive');
	const byKind = eligibleByKind(dataset);
	const strata: { kind: Kind; basis: string; eligible: number }[] = [];
	for (const kind of Object.keys(REVIEWABLE) as Kind[]) {
		const counts = new Map<string, number>();
		for (const record of byKind.get(kind) ?? []) {
			const basis = String(record.basis ?? '');
			counts.set(basis, (counts.get(basis) ?? 0) + 1);
		}
		for (const basis of [...counts.keys()].sort()) {
			strata.push({ kind, basis, eligible: counts.get(basis) as number });
		}
	}
	const allocation = pilotAllocation(strata, size);

	const drawn: PilotEntry[] = [];
	for (const stratum of allocation) {
		const candidates = (byKind.get(stratum.kind) ?? []).filter(
			(r) => String(r.basis ?? '') === stratum.basis
		);
		candidates.sort((a, b) => {
			const da = pilotDigest(seed, stratum.kind, a.id);
			const db = pilotDigest(seed, stratum.kind, b.id);
			return da < db ? -1 : da > db ? 1 : a.id < b.id ? -1 : a.id > b.id ? 1 : 0;
		});
		for (const record of candidates.slice(0, stratum.allocated)) {
			drawn.push({ kind: stratum.kind, id: record.id, basis: stratum.basis });
		}
	}

	drawn.sort((a, b) => {
		const da = pilotDigest(seed, a.kind, a.id);
		const db = pilotDigest(seed, b.kind, b.id);
		return da < db ? -1 : da > db ? 1 : 0;
	});
	return { entries: drawn, allocation };
}

/** The file, byte for byte, with LF endings and a trailing newline. */
export function renderPilotSample(dataset: any, seed: string = PILOT_SEED, size: number = PILOT_SIZE): string {
	const { entries } = pilotSample(dataset, seed, size);
	return [PILOT_HEADER, ...entries.map((e) => `${e.kind}\t${e.id}\t${e.basis}`)].join('\n') + '\n';
}

/** The sidecar: the seed, the size and the dataset hash the draw was made on. */
export function renderPilotMeta(dataset: any, seed: string = PILOT_SEED, size: number = PILOT_SIZE): string {
	return JSON.stringify({ seed, size, datasetHash: dataset?.meta?.datasetHash ?? '' }, null, 2) + '\n';
}

/** Read the committed sample. The header must be the one this module writes. */
export function parsePilotSample(text: string): PilotEntry[] {
	const lines = text.replace(/\r\n/g, '\n').split('\n').filter((line) => line.length > 0);
	if (!lines.length || lines[0] !== PILOT_HEADER) {
		throw new Error(`the sample's first line must be "${PILOT_HEADER}"`);
	}
	return lines.slice(1).map((line, i) => {
		const fields = line.split('\t');
		if (fields.length !== 3) throw new Error(`line ${i + 2}: ${fields.length} fields, expected 3`);
		const [kind, id, basis] = fields;
		if (!REVIEWABLE[kind as Kind]) throw new Error(`line ${i + 2}: unknown kind "${kind}"`);
		return { kind: kind as Kind, id, basis };
	});
}

export function readPilotSample(root: string, file: string = PILOT_FILE): PilotEntry[] {
	return parsePilotSample(readFileSync(join(root, file), 'utf8'));
}

export interface PilotQueue {
	/** The file's records that the dataset still holds, in file order. */
	items: { kind: Kind; id: string; label: string }[];
	/** Records the file names that the dataset no longer holds. */
	missing: string[];
	/** The number of records the file names, whether or not they exist. */
	total: number;
}

/**
 * The queue the verify tab shows in pilot mode: the file's order, not the risk
 * queue's. A named record that is gone is skipped, not invented; the caller
 * prints the names at start-up so the gap is visible.
 */
export function pilotQueue(root: string, file: string = PILOT_FILE): PilotQueue {
	const entries = readPilotSample(root, file);
	const dataset = JSON.parse(readFileSync(join(root, 'src', 'generated', 'dataset.json'), 'utf8'));
	const items: PilotQueue['items'] = [];
	const missing: string[] = [];
	for (const entry of entries) {
		const record = ((dataset[entry.kind] ?? []) as any[]).find((r) => r.id === entry.id);
		if (!record) {
			missing.push(`${entry.kind}/${entry.id}`);
			continue;
		}
		items.push({ kind: entry.kind, id: entry.id, label: recordLabel(entry.kind, record) });
	}
	return { items, missing, total: entries.length };
}

/** The label the review queue shows for a record. One definition for both queues. */
export function recordLabel(kind: Kind, record: any): string {
	if (kind === 'positions') return `${record.roleTitle ?? record.role} — ${record.holder}`;
	if (kind === 'relationships') return `${record.from} → ${record.to} (${record.type})`;
	return record.title ?? record.id;
}

function main(): number {
	const datasetPath = join(ROOT, 'src', 'generated', 'dataset.json');
	const dataset = JSON.parse(readFileSync(datasetPath, 'utf8'));
	const text = renderPilotSample(dataset);
	writeFileSync(join(ROOT, PILOT_FILE), text, 'utf8');
	writeFileSync(join(ROOT, PILOT_META_FILE), renderPilotMeta(dataset), 'utf8');
	const entries = parsePilotSample(text);
	console.log(`\n  pilot sample  ${PILOT_FILE}: ${entries.length} records, seed ${PILOT_SEED}`);
	console.log(`  drawn from    ${dataset?.meta?.datasetHash ?? '(no hash)'}  (${PILOT_META_FILE})\n`);
	return 0;
}

const runDirectly = process.argv[1] && import.meta.url === pathToFileURL(process.argv[1]).href;
if (runDirectly) process.exit(main());
